import { parseGitHubUrl } from "../helpers/github";
import { createPostgresPool } from "./postgres-driver";
export class PostgresIssueStore {
    _pool;
    constructor(pool) {
        this._pool = pool;
    }
    async initialize() {
        await this._withClient(async (client) => {
            await client.queryObject `
        CREATE TABLE IF NOT EXISTS text_vector_embeddings_tracked_issues (
          owner TEXT NOT NULL,
          repo TEXT NOT NULL,
          issue_number INTEGER NOT NULL,
          created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
          PRIMARY KEY (owner, repo, issue_number)
        )
      `;
            await client.queryObject `
        CREATE INDEX IF NOT EXISTS text_vector_embeddings_tracked_issues_owner_repo_idx
        ON text_vector_embeddings_tracked_issues (owner, repo)
      `;
        });
    }
    async getIssueNumbers(owner, repo) {
        const result = await this._withClient((client) => client.queryObject `
          SELECT issue_number
          FROM text_vector_embeddings_tracked_issues
          WHERE owner = ${owner} AND repo = ${repo}
          ORDER BY issue_number
        `);
        return result.rows.map((row) => row.issue_number);
    }
    async addIssue(url) {
        const { owner, repo, issue_number: issueNumber } = parseGitHubUrl(url);
        await this._withClient((client) => client.queryObject `
          INSERT INTO text_vector_embeddings_tracked_issues (owner, repo, issue_number)
          VALUES (${owner}, ${repo}, ${issueNumber})
          ON CONFLICT (owner, repo, issue_number) DO NOTHING
        `);
    }
    async removeIssue(url) {
        const { owner, repo, issue_number: issueNumber } = parseGitHubUrl(url);
        await this._withClient((client) => client.queryObject `
          DELETE FROM text_vector_embeddings_tracked_issues
          WHERE owner = ${owner} AND repo = ${repo} AND issue_number = ${issueNumber}
        `);
    }
    async updateIssue(currentUrl, newUrl) {
        if (currentUrl === newUrl) {
            return;
        }
        const currentIssue = parseGitHubUrl(currentUrl);
        const nextIssue = parseGitHubUrl(newUrl);
        await this._withClient(async (client) => {
            await client.queryObject `BEGIN`;
            try {
                await client.queryObject `
          DELETE FROM text_vector_embeddings_tracked_issues
          WHERE owner = ${currentIssue.owner} AND repo = ${currentIssue.repo} AND issue_number = ${currentIssue.issue_number}
        `;
                await client.queryObject `
          INSERT INTO text_vector_embeddings_tracked_issues (owner, repo, issue_number)
          VALUES (${nextIssue.owner}, ${nextIssue.repo}, ${nextIssue.issue_number})
          ON CONFLICT (owner, repo, issue_number) DO NOTHING
        `;
                await client.queryObject `COMMIT`;
            }
            catch (error) {
                await client.queryObject `ROLLBACK`;
                throw error;
            }
        });
    }
    async getAllRepositories() {
        const result = await this._withClient((client) => client.queryObject `
          SELECT
            owner,
            repo,
            array_agg(issue_number ORDER BY issue_number) AS issue_numbers
          FROM text_vector_embeddings_tracked_issues
          GROUP BY owner, repo
          ORDER BY owner, repo
        `);
        return result.rows.map((row) => ({
            owner: row.owner,
            repo: row.repo,
            issueNumbers: row.issue_numbers ?? [],
        }));
    }
    async hasData() {
        const result = await this._withClient((client) => client.queryObject `
          SELECT EXISTS (SELECT 1 FROM text_vector_embeddings_tracked_issues) AS has_data
        `);
        return result.rows[0]?.has_data ?? false;
    }
    async close() {
        await this._pool.end();
    }
    async _withClient(callback) {
        const client = await this._pool.connect();
        try {
            return await callback(client);
        }
        finally {
            client.release();
        }
    }
}
function getDatabaseUrl() {
    const databaseUrl = process.env.DATABASE_URL?.trim();
    if (!databaseUrl) {
        throw new Error("DATABASE_URL is required.");
    }
    return databaseUrl;
}
export async function createPostgresIssueStore(databaseUrl = getDatabaseUrl()) {
    const pool = await createPostgresPool(databaseUrl);
    const issueStore = new PostgresIssueStore(pool);
    await issueStore.initialize();
    return issueStore;
}
