import { SuperVoyage } from "./voyage";
export class Embedding extends SuperVoyage {
    context;
    constructor(client, context) {
        super(client, context);
        this.context = context;
    }
    async createEmbedding(text, inputType = "document") {
        if (text === null) {
            throw new Error("Text is null");
        }
        else {
            const embeddings = await this.createEmbeddings([text], inputType);
            return embeddings[0] ?? [];
        }
    }
    async createEmbeddings(texts, inputType = "document") {
        if (texts.length === 0) {
            return [];
        }
        const response = await this.client.embed({
            input: texts,
            model: "voyage-4-large",
            outputDimension: 1024,
            inputType,
        });
        if (!response.data) {
            return [];
        }
        return response.data.map((item) => item?.embedding ?? []);
    }
}
